<?php
use Illuminate\Support\Facades\Route;use App\Http\Controllers\AuthController;use App\Http\Controllers\ProductController;use App\Http\Controllers\UserController;use App\Http\Controllers\SecurityLogController;use App\Http\Controllers\SupplierController;
Route::get('/',fn()=>redirect()->route('products.index'));
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLoginForm'])->name('login');Route::post('/login',[AuthController::class,'login'])->name('login.post');Route::get('/register',[AuthController::class,'showRegistrationForm'])->name('register');Route::post('/register',[AuthController::class,'register'])->name('register.post');Route::get('/verify-otp',[AuthController::class,'showOtpForm'])->name('otp.form');Route::post('/verify-otp',[AuthController::class,'verifyOtp'])->name('otp.verify');Route::post('/verify-otp/resend',[AuthController::class,'resendOtp'])->name('otp.resend');});
Route::middleware('auth')->group(function(){Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/products',[ProductController::class,'index'])->name('products.index');Route::get('/products/create',[ProductController::class,'create'])->name('products.create');Route::post('/products',[ProductController::class,'store'])->name('products.store');Route::get('/products/{id}/edit',[ProductController::class,'edit'])->name('products.edit');Route::put('/products/{id}',[ProductController::class,'update'])->name('products.update');Route::delete('/products/{id}',[ProductController::class,'delete'])->name('products.delete');Route::post('/products/{id}/stock-in',[ProductController::class,'stockIn'])->name('products.stockIn');Route::post('/products/{id}/stock-out',[ProductController::class,'stockOut'])->name('products.stockOut');Route::get('/users',[UserController::class,'index'])->name('users.index');Route::get('/users/{id}/edit',[UserController::class,'edit'])->name('users.edit');Route::put('/users/{id}',[UserController::class,'update'])->name('users.update');Route::get('/security-logs',[SecurityLogController::class,'index'])->name('security.logs');Route::get('/suppliers',[SupplierController::class,'index'])->name('suppliers.index');Route::get('/suppliers/create',[SupplierController::class,'create'])->name('suppliers.create');Route::post('/suppliers',[SupplierController::class,'store'])->name('suppliers.store');Route::get('/suppliers/{supplier}/edit',[SupplierController::class,'edit'])->name('suppliers.edit');Route::put('/suppliers/{supplier}',[SupplierController::class,'update'])->name('suppliers.update');Route::delete('/suppliers/{supplier}',[SupplierController::class,'destroy'])->name('suppliers.destroy');});
